  await check("the Focus slider stands on four stops — the app's choice and three lines (Nov 27 2026)", async (ctx) => {
    // Kasra's 3–4 range rule (Nov 27 2026, from his screenshot):
    // the Focus slider stood above the range with a stop per
    // outcome line, so its STANDING stops cap at four — the app's
    // choice plus the first three complete lines. A chosen line
    // outside the standing four takes the fourth seat beside the
    // app's choice and the first two lines, so the pick always
    // stands visible and selected. The profile still OFFERS up to
    // six complete lines — the cap is on the slider's standing
    // display only; the pop-up form's full list is untouched.
    const LINES = [
      "Naming the feeling before it grows",
      "Saying the thought out loud once",
      "Letting the tight chest soften",
      "Catching the spiral early today",
      "Keeping my own words on record",
      "Ending the day a little clearer",
    ];
    const fullProfile = {
      ...PROFILE,
      outcome_statements: LINES.map((outcome) => ({ outcome, from_feature: "Voice entries" })),
      desired_outcomes: [],
    };
    const stopsOf = () => {
      const slider = ctx.container.querySelector('[data-testid="hook-picks-focus-slider"]');
      if (!slider) throw new Error("the Focus slider did not render");
      return [...slider.querySelectorAll(".pick-slider-stop")].map((b) => b.dataset.value);
    };
    await inHookCta(
      ctx,
      {
        getAppProfiles: async () => ({ profiles: [fullProfile] }),
        getAppProfile: async () => fullProfile,
        createHookCtaProject: async () => hookRow({ id: "hook-cta-1", hook_focus: LINES[5] }),
        getGenerations: async () => ({ generations: [] }),
      },
      "",
      async () => {
        const stops = stopsOf();
        if (stops.join("|") !== ["", LINES[0], LINES[1], LINES[5]].join("|")) {
          throw new Error(`the Focus slider stands on ${JSON.stringify(stops)} — the chosen sixth line must take the fourth seat`);
        }
        const knob = ctx.container.querySelector('[data-testid="hook-picks-focus-knob"]');
        if (!knob || knob.getAttribute("aria-valuenow") !== "3") {
          throw new Error("the Focus knob does not stand on the chosen line's fourth seat");
        }
      }
    );
    // Unmount between the two scenarios: a bare re-render of the
    // same page component would keep the first mount's draft
    // state (the chosen focus included) instead of loading the
    // second scenario's project.
    await act(async () => ctx.root.render(null));
    await inHookCta(
      ctx,
      {
        getAppProfiles: async () => ({ profiles: [fullProfile] }),
        getAppProfile: async () => fullProfile,
        createHookCtaProject: async () => hookRow({ id: "hook-cta-2" }),
        getGenerations: async () => ({ generations: [] }),
      },
      "",
      async () => {
        const stops = stopsOf();
        if (stops.join("|") !== ["", LINES[0], LINES[1], LINES[2]].join("|")) {
          throw new Error(`the Focus slider stands on ${JSON.stringify(stops)} — the app's choice and the first three lines belong there`);
        }
      }
    );
  });

  await check("the Focus slider's left stop takes: App's choice clears a saved line and the clear saves (Nov 28 2026)", async (ctx) => {
    // Kasra's live report (Nov 28 2026, with screenshot): on the
    // Focus slider the very LEFT stop — "Let the app choose",
    // value "" — could not be activated. Tapping it recorded
    // nothing: the draft reducers treated a falsy pick value as
    // no pick at all (the pick record skipped it) and deleted
    // the edit that would have cleared the saved line, so
    // editValue fell back to the saved line and the knob snapped
    // back to it — the mirror of the ADR 0248/0373 dead tap.
    // The fix: a pick-shaped edit restates only when its value
    // equals the SAVED value; a "" pick over a saved line is a
    // real edit, the pick record remembers it, and the autosave
    // carries the clear to the server copy.
    const LINES = [
      "Naming the feeling before it grows",
      "Saying the thought out loud once",
      "Letting the tight chest soften",
      "Catching the spiral early today",
      "Keeping my own words on record",
      "Ending the day a little clearer",
    ];
    const fullProfile = {
      ...PROFILE,
      outcome_statements: LINES.map((outcome) => ({ outcome, from_feature: "Voice entries" })),
      desired_outcomes: [],
    };
    const row = hookRow({ id: "hook-cta-1", hook_focus: LINES[5] });
    const patches = [];
    await inHookCta(
      ctx,
      {
        getAppProfiles: async () => ({ profiles: [fullProfile] }),
        getAppProfile: async () => fullProfile,
        createHookCtaProject: async () => row,
        updateStudioProject: async (_id, patch) => {
          patches.push(patch);
          return { ...row, ...patch };
        },
        getGenerations: async () => ({ generations: [] }),
      },
      "",
      async () => {
        const knob = () => ctx.container.querySelector('[data-testid="hook-picks-focus-knob"]');
        if (!knob() || knob().getAttribute("aria-valuenow") !== "3") {
          throw new Error("the Focus knob does not stand on the saved line's fourth seat before the tap");
        }
        const leftStop = ctx.container.querySelector('[data-testid="hook-picks-focus-auto"]');
        if (!leftStop) throw new Error("the Focus slider carries no left (app's choice) stop");
        await clickEl(ctx, leftStop);
        await act(async () => {});
        if (!knob() || knob().getAttribute("aria-valuenow") !== "0") {
          throw new Error(`the Focus knob did not take the left stop — it rests at ${knob()?.getAttribute("aria-valuenow")}, not 0`);
        }
        const value = ctx.container.querySelector('[data-testid="hook-picks-focus-value"]');
        if (!value || value.textContent.trim() !== "Let the app choose") {
          throw new Error(`the Focus slider names ${JSON.stringify(value?.textContent?.trim())} under the knob, not "Let the app choose"`);
        }
        await act(async () => { await new Promise((r) => setTimeout(r, 1400)); });
        if (!patches.some((p) => p.hook_focus === "")) {
          throw new Error(`the clear never saved — no patch carried hook_focus "": ${JSON.stringify(patches)}`);
        }
        if (!knob() || knob().getAttribute("aria-valuenow") !== "0") {
          throw new Error("the Focus knob snapped back to the saved line after the clear saved");
        }
      }
    );
  });

  await check("every pop-up wears the tour's dim, and one secondary button serves the app (ADRs 0335/0336)", async () => {
    // Source pins, in the suite's css-reading precedent: the shared
    // dialog overlay (every confirm dialog) dims with .pop-scrim;
    // the scrim is the tour's 55% black; the shared Button carries
    // exactly one secondary treatment — the Show me around pill —
    // and the retired outline/ghost variants stay retired.
    const fs = require("fs");
    const path = require("path");
    const read = (rel) => fs.readFileSync(path.join(__dirname, "..", rel), "utf8");
    const css = read("src/index.css");
    if (!css.includes(".pop-scrim") || !css.includes("rgba(0, 0, 0, 0.8)")) {
      throw new Error("the shared pop-up scrim is not the tour's combined dim (ADRs 0335/0338)");
    }
    if (!css.includes(".btn-secondary-pill") || !css.includes("border-radius: 9999px")) {
      throw new Error("the unified secondary pill is missing from the stylesheet (ADR 0336)");
    }
    const dialog = read("src/components/ui/dialog.jsx");
    if (!dialog.includes("pop-scrim")) {
      throw new Error("the shared dialog overlay does not wear the pop-up scrim (ADR 0335)");
    }
    // ADR 0341: the angle and Focus pop-ups render through a
    // portal on the document body, like the tour overlay, so
    // their dim covers the whole screen.
    for (const rel of ["src/components/studio/SelectionPanels.jsx", "src/components/studio/HookPicksControl.jsx"]) {
      const src = read(rel);
      if (!src.includes("createPortal") || !src.includes("document.body")) {
        throw new Error(`a pop-up does not render through the body portal (ADR 0341): ${rel}`);
      }
    }
    const button = read("src/components/ui/button.jsx");
    if (button.includes("outline:") || button.includes("ghost:")) {
      throw new Error("a retired secondary variant is back in the shared Button (ADR 0336)");
    }
    if (!button.includes("btn-secondary-pill")) {
      throw new Error("the shared Button's secondary is not the unified pill (ADR 0336)");
    }
    // A picked member of a pair (thumb-selected) takes the same
    // pill radius, so a pair never mixes shapes.
    const pickedRule = css.split(".thumb-selected {")[1].split("}")[0];
    if (!pickedRule.includes("border-radius: 9999px")) {
      throw new Error("a picked pick-family member does not take the pill radius (ADR 0336)");
    }
  });

  await check("the Focus refresh replaces the outcome layer and offers the fresh lines at once", async (ctx) => {
    // ADR 0288 (Kasra's order, Nov 23 2026): the button beside the
    // Focus pick refreshes the profile's outcome layer from its
    // stored facts — a stored list carrying comma-chopped fragments
    // ("and growth over time", from his own saved profile) is
    // replaced whole, and the fresh lines are the pick's options
    // without a page reload.
    const FRAGMENT = "and growth over time";
    const FRESH = "A word for the tight feeling before sleep";
    const staleProfile = {
      ...PROFILE,
      outcome_statements: [{ outcome: "A name for what you felt", from_feature: "Voice entries" }],
      desired_outcomes: [FRAGMENT],
    };
    const freshProfile = {
      ...PROFILE,
      outcome_statements: [{ outcome: FRESH, from_feature: "Voice entries" }],
      desired_outcomes: ["See your own rhythms and growth over time"],
    };
    const calls = [];
    await inHookCta(
      ctx,
      {
        getAppProfiles: async () => ({ profiles: [staleProfile] }),
        getAppProfile: async () => staleProfile,
        createHookCtaProject: async () => hookRow({ id: "hook-cta-1" }),
        refreshProfileOutcomes: async (id) => { calls.push(id); return freshProfile; },
      },
      "",
      async () => {
        const card = ctx.container.querySelector('[data-testid="hook-cta-hook-card"]');
        if (!card) throw new Error("the Hook card did not render");
        const offeredFocusValues = () => [...card.querySelectorAll('[data-testid="hook-picks-focus"] button[data-value]')].map((b) => b.dataset.value);
        const before = offeredFocusValues();
        if (before.includes(FRAGMENT)) {
          throw new Error("the fragment was offered as a focus line before the refresh (ADR 0307: a fragment is never offered)");
        }
        const refresh = card.querySelector('[data-testid="hook-picks-focus-refresh"]');
        if (!refresh) throw new Error("the Focus refresh control did not render");
        await clickEl(ctx, refresh);
        await act(async () => {});
        await act(async () => {});
        if (calls.length !== 1 || calls[0] !== PROFILE.id) {
          throw new Error(`the refresh called the endpoint ${JSON.stringify(calls)}, expected once for the profile`);
        }
        const after = offeredFocusValues();
        if (!after.includes(FRESH)) {
          throw new Error("the fresh outcome line is not offered after the refresh");
        }
        if (after.includes(FRAGMENT)) {
          throw new Error("the fragment is still offered after the refresh");
        }
      }
    );
  });

