        const panel = first.querySelector('[data-testid="history-detail-panel"]');
        if (!panel) throw new Error("the card shows no record beside its clip");
        if (!first.contains(panel)) throw new Error("the record is not attached inside its card");
        if (!panel.querySelector('[data-testid="history-context"]')?.textContent.includes("Record the emotion suggestions.")) throw new Error("useful demo context missing");
        for (const label of ["Download", "Demo + CTA"]) {
          if (!first.textContent.includes(label)) throw new Error(`History lost ${label}`);
        }
        // Delete is icon-only and shares the Download row below the video, so
        // removing a render never floats over the footage.
        if (!first.querySelector('button[aria-label="Delete this render"]')) throw new Error("History lost Delete");
        const summary = first.querySelector('[data-testid="history-summary"]');
        for (const text of ["Journal", "Find your next thought.", "Not posted yet"]) {
          if (!summary?.textContent.includes(text)) throw new Error(`attached identity/result missing: ${text}`);
        }
        // An untouched render says so once. Three separate negatives on the
        // most common row in History read as a list of failures.
        for (const gone of ["Views not recorded", "Not rated"]) {
          if (summary?.textContent.includes(gone)) {
            throw new Error(`an untouched render still prints ${JSON.stringify(gone)}`);
          }
        }
        // Order is the priority. The summary reads as three blocks:
        // identity first — app, status, date, with the provenance facts
        // (model, template and script versions) riding in the same header
        // row as tidy chips instead of a loose technical line — then the
        // hook headline, then the results line. The summary is record
        // content (ADR 0150): it opens the record beside the clip, and
        // the joined finished → posted journey line and the whole-video
        // verdict follow it, journey first and the verdict under it, so
        // the card's right side opens with which render this is, then
        // holds the video's state and the founder's one call together.
        const blocks = [...summary.children];
        if (blocks.length !== 3) {
          throw new Error(`the summary should read as three blocks, saw ${blocks.length}`);
        }
        if (!blocks[0].textContent.includes("Journal") || !blocks[0].textContent.includes("Completed")) {
          throw new Error("the summary does not open with app identity and its status");
        }
