  // One treatment for every filter control (ADR 0161): the shared pill
  // skin carries the filter class and the shared focus ring, the
  // stylesheet states the active look in the selection indigo, and a
  // filter holding a non-default value says so on its face — which
  // filters are on is visible without opening any of them.
  await check("every filter control wears the one treatment and an active filter reads active", async (ctx) => {
    const pickerSource = fs.readFileSync(path.join(SRC, "components", "AppPicker.jsx"), "utf8");
    if (!/PILL_SELECT_CLASS\s*=\s*"[^"]*filter-control/.test(pickerSource)) {
      throw new Error("the shared filter skin lost the filter-control class");
    }
    if (!/PILL_SELECT_CLASS\s*=\s*"[^"]*focus-ring/.test(pickerSource)) {
      throw new Error("the shared filter skin lost the shared focus ring");
    }
    const css = fs.readFileSync(path.join(SRC, "index.css"), "utf8");
    if (!/\.filter-control\[data-active="true"\][\s\S]{0,300}?--indigo-45/.test(css)) {
      throw new Error("index.css does not define the active filter state in the selection indigo");
    }
    if (!/\.filter-control\[aria-pressed="true"\]/.test(css)) {
      throw new Error("index.css does not carry the pressed state for filter toggles");
    }
    const GenerationHistory = load("pages/GenerationHistory.jsx").default;
    const previousParams = global.__SMOKE_PARAMS;
    try {
      await withApi({
        getGenerationHistory: async () => ({ generations: [{
          ...COMPLETED,
          id: "filter-1",
          hook_line: "A pier at dawn",
          post_kit: POST_KIT,
          audience: "Night scrollers",
        }] }),
        getAppProfiles: async () => ({ profiles: [PROFILE] }),
      }, async () => {
        global.__SMOKE_PARAMS = "?status=failed&q=pier";
        await mount(GenerationHistory)(ctx);
        const search = ctx.container.querySelector('[data-testid="history-search"]');
        if (!search.className.includes("filter-control")) {
          throw new Error("the History search does not wear the filter treatment");
        }
        if (search.getAttribute("data-active") !== "true") {
          throw new Error("a search holding text does not read as an active filter");
        }
        if (ctx.container.querySelector('[data-testid="history-copy-filter"]')) {
          throw new Error("the copy filter survives its removal from the filter bar");
        }
        const status = ctx.container.querySelector("#history-status-filter");
        if (status.getAttribute("data-active") !== "true") {
          throw new Error("a chosen status does not read as an active filter");
        }
        if (!status.querySelector(".pick-slider")) {
          throw new Error("the status filter does not wear the unified slider (Nov 27 2026)");
        }
        const sort = ctx.container.querySelector('[data-testid="history-sort"]');
        if (!sort.className.includes("filter-control")) {
          throw new Error("the sort select does not wear the filter treatment");
        }
        if (sort.getAttribute("data-active")) {
          throw new Error("the sort on its default reads as an active filter");
        }
        const picker = ctx.container.querySelector('[aria-label="Filter by app"]');
        if (!picker.className.includes("filter-control")) {
          throw new Error("the app picker does not wear the filter treatment");
        }
        if (picker.getAttribute("data-active")) {
          throw new Error("the app picker on All apps reads as an active filter");
        }
        const more = [...ctx.container.querySelectorAll("button")].find((b) => b.textContent.includes("More filters"));
        if (!more || more.getAttribute("data-active") !== "true") {
          throw new Error("More filters does not read as active while a filter behind it is on");
        }
      });
    } finally {
      global.__SMOKE_PARAMS = previousParams;
    }
  });

  // The sort menu is drawn by the app, not the OS (ADR 0162):
  // opening it shows the app's own listbox. The status filter is
  // the unified slider now (Nov 27 2026): its six standings are
  // stops, the URL's status stands picked, and tapping another
  // stop applies the filter — the URL param moves, exactly as
  // the dropdown's choice did.
  await check("the sort menu is app-drawn and the status slider applies its pick", async (ctx) => {
    const GenerationHistory = load("pages/GenerationHistory.jsx").default;
    const previousParams = global.__SMOKE_PARAMS;
    const previousNavigations = global.__SMOKE_NAVIGATIONS;
    global.__SMOKE_NAVIGATIONS = [];
    try {
      await withApi({
        getGenerationHistory: async () => ({ generations: [{
          ...COMPLETED,
          id: "menu-1",
          hook_line: "A pier at dawn",
          audience: "Night scrollers",
        }] }),
        getAppProfiles: async () => ({ profiles: [PROFILE] }),
      }, async () => {
        global.__SMOKE_PARAMS = "?status=failed";
        await mount(GenerationHistory)(ctx);
        const status = ctx.container.querySelector("#history-status-filter");
        if (!status) throw new Error("History lost the status filter");
        const statusSlider = status.querySelector(".pick-slider");
        if (!statusSlider) throw new Error("the status filter does not wear the unified slider");
        const stops = [...statusSlider.querySelectorAll("button[data-value]")];
        if (stops.length !== 6) {
          throw new Error(`the status slider carries ${stops.length} stops, not the six statuses`);
        }
        const chosen = stops.find((o) => o.dataset.value === "failed");
        if (!chosen || chosen.getAttribute("aria-pressed") !== "true") {
          throw new Error("the current status does not stand picked on its slider");
        }
        if (stops.some((o) => o !== chosen && o.getAttribute("aria-pressed") === "true")) {
          throw new Error("more than the current status stands picked");
        }
        // Tapping a different stop applies the filter — the URL
        // param moves, exactly as the dropdown's choice did.
        const completed = stops.find((o) => o.dataset.value === "completed");
        await clickEl(ctx, completed);
        const went = (global.__SMOKE_NAVIGATIONS || []).map((to) => (to && to.search) || "");
        if (!went.some((search) => new URLSearchParams(search).get("status") === "completed")) {
          throw new Error(`choosing a status did not navigate the status param: ${JSON.stringify(went)}`);
        }
        // The keyboard opens and closes a menu too: ArrowDown opens the
        // sort menu, Escape closes it without changing anything.
        const sort = ctx.container.querySelector('[data-testid="history-sort"]');
        await act(async () => {
          sort.dispatchEvent(new dom.window.KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }));
        });
        await act(async () => {});
        if (sort.getAttribute("aria-expanded") !== "true" || !sort.closest(".app-select")?.querySelector('[role="listbox"]')) {
          throw new Error("ArrowDown did not open the sort menu");
        }
        await act(async () => {
          sort.dispatchEvent(new dom.window.KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
        });
        await act(async () => {});
        if (sort.getAttribute("aria-expanded") !== "false" || ctx.container.querySelector('[role="listbox"]')) {
          throw new Error("Escape did not close the sort menu");
        }
      });
    } finally {
      global.__SMOKE_PARAMS = previousParams;
      global.__SMOKE_NAVIGATIONS = previousNavigations;
    }
  });

